import{a as e}from"./chunk-GOJJMUIS.js";var n=[{label:"Start",path:"/",exact:!0},{label:"Events",path:"/events"},{label:"Galerie",path:"/gallery"},{label:"FAQ",path:"/faq"},{label:"Mitglied werden",path:"/mitglied-werden"}],i=[{label:"Instagram",href:"https://www.instagram.com/vaidaisnotdead_ev/",external:!0},{label:"Facebook",href:"https://www.facebook.com/vaidaisnotdead/",external:!0},{label:"E-Mail",href:`mailto:${e}`,external:!1}],a=[{src:"/facebook-jam-session.jpg",alt:"\xD6ffentlich sichtbarer Flyer f\xFCr eine Jam-Session von Vaida is not dead e.V.",caption:"Handgemachter Flyer f\xFCr ein offenes Session-Format. Der Ton geht eher in Richtung Szene-Aushang als in Richtung Werbebanner."},{src:"/vaidaisnotdead-logo.png",alt:"Logo von Vaida is not dead e.V.",caption:"Die aktuelle Wort-Bild-Marke bleibt der st\xE4rkste visuelle Anker und funktioniert auch alleine als Motiv."},{src:"/facebook-page-preview.jpg",alt:"\xD6ffentlich sichtbare Vorschaubild-Kachel der Facebook-Seite",caption:"Kleiner \xF6ffentlicher Einblick in den Social-Auftritt. Auch hier wirkt alles eher rau, direkt und selbstgemacht."},{src:"/gallery-tile-01.jpg",alt:"\xD6ffentlich sichtbarer Bildausschnitt aus dem Facebook-Auftritt von Vaida is not dead e.V.",caption:"Erstes Zusatzmotiv f\xFCr die Gallery-Seite, um dem Auftritt einen einfacheren, aber echten Bilderrahmen zu geben."},{src:"/gallery-tile-02.jpg",alt:"Kleine \xF6ffentlich sichtbare Bildkachel aus dem Facebook-Auftritt",caption:"Kleine Vorschaukachel aus dem \xF6ffentlichen Material. Nicht Hochglanz, aber genau darin liegt der Reiz."}],r=[{question:"Was soll hier f\xFCr Veranstaltungen auftauchen?",answer:"Im Fokus stehen DIY-Konzertabende, offene Sessions und Formate, die Jugend- und Subkultur in Viechtach sichtbar machen. Die Seite soll diese Termine k\xFCnftig gesammelt und klar lesbar zeigen."},{question:"Wo erfahre ich aktuelle Termine, solange die Seite weiter w\xE4chst?",answer:"Bis alle Inhalte final eingebunden sind, laufen kurzfristige Hinweise weiterhin am schnellsten \xFCber Instagram und Facebook. Die neue Events-Seite bereitet aber genau diesen Wechsel vor."},{question:"Kann ich mit einer Band oder einem Format anfragen?",answer:"Ja. Am besten kurz und direkt per Mail oder \xFCber Instagram schreiben: Wer seid ihr, was spielt ihr, und was f\xFCr einen Rahmen sucht ihr?"},{question:"Warum sieht die Seite so reduziert aus?",answer:"Weil sie n\xE4her an Flyern, Clubw\xE4nden und direkter Kommunikation bleiben soll als an einem glatten Event-Portal. Der Auftritt darf roh sein, solange er klar funktioniert."},{question:"Wie kann ich den Verein unterst\xFCtzen?",answer:"Mitgliedschaft ist ein Weg. Dazu kommen Hilfe bei Aufbau, Awareness, Technik, Orga, Einlass oder einfach regelm\xE4\xDFiges Mittragen von Abenden und Strukturen."}],s=[{kind:"foerder",label:"F\xF6rdermitgliedschaft",title:"F\xFCr Leute, die den Verein regelm\xE4\xDFig unterst\xFCtzen wollen, ohne im Alltag jedes Mal aktiv eingebunden zu sein.",intro:"Diese Form passt, wenn du Konzerte, Sessions und laufende Vereinsarbeit mittragen willst, aber eher \xFCber kontinuierliche Unterst\xFCtzung als \xFCber feste Aufgaben vor Ort.",details:["hilft dabei, Miete, Technik, Material, Infrastruktur und laufende Kosten stabiler zu tragen","passt, wenn du die Szene st\xE4rken willst, aber nicht regelm\xE4\xDFig bei Aufbau, Theke oder Orga eingebunden sein kannst","bleibt nah dran am Verein, ohne dass daraus automatisch eine praktische Rolle bei jedem Abend wird"],note:"F\xF6rdermitgliedschaft bedeutet: R\xFCckhalt geben, damit Dinge \xFCberhaupt stattfinden k\xF6nnen.",cta:"Im Formular als F\xF6rdermitgliedschaft angeben",imageSrc:"/logo.png",imageAlt:"Logo von vaida is not dead e.V. als visuelle Marke f\xFCr die F\xF6rdermitgliedschaft",symbol:"FM"},{kind:"aktiv",label:"Aktive Mitgliedschaft",title:"F\xFCr Leute, die bei Abenden, Planung und Vereinsarbeit praktisch mitziehen wollen.",intro:"Hier geht es nicht nur um Unterst\xFCtzung im Hintergrund, sondern um Mitarbeit in echten Situationen: Aufbau, Theke, Technik, Awareness, Booking oder laufende Orga.",details:["nah dran an Planung, Umsetzung und den realen Abenden vor Ort","passt, wenn du Zeit, Ideen, Skills oder regelm\xE4\xDFige Energie einbringen willst","macht aus losem Umfeld eine belastbare DIY-Struktur im Bayerischen Wald"],note:"Aktive Mitgliedschaft bedeutet: nicht nur kommen, sondern mitverantworten.",cta:"Im Formular als aktive Mitgliedschaft angeben",imageSrc:"/gallery-tile-01.jpg",imageAlt:"Raue Fotofl\xE4che aus dem Umfeld von vaida is not dead als Motiv f\xFCr aktive Mitarbeit",symbol:"AK"}];export{n as a,i as b,a as c,r as d,s as e};
